package com.libtrack.circulation;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.libtrack.auth.*;
import com.libtrack.catalogue.*;
import java.time.Instant;
import java.time.LocalDate;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.*;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.MediaType;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.test.web.servlet.*;
import com.libtrack.LibTrackIntegrationTest;
@LibTrackIntegrationTest
class CirculationIntegrationTest {
 private static final String PASSWORD="Sufficiently Long Test Password 1!";
 @Autowired MockMvc mvc;@Autowired UserAccountRepository accounts;@Autowired PasswordEncoder encoder;@Autowired BookRepository books;@Autowired BookCopyRepository copies;@Autowired BorrowRequestRepository requests;@Autowired LoanRepository loans;@Autowired LibraryHolidayRepository holidays;@Autowired DueDateService dueDates;
 private final ObjectMapper mapper=new ObjectMapper();private UserAccount librarian;private MockHttpSession lib;
 @BeforeEach void setup()throws Exception{String t=UUID.randomUUID().toString();librarian=accounts.saveAndFlush(UserAccount.initialLibrarian("lib-"+t+"@example.edu",encoder.encode(PASSWORD)));lib=login(librarian);}
 @Test void memberRequestsAreOwnedAndRestrictedBooksCannotBeRequested()throws Exception{MockHttpSession student=login(member(AccountRole.STUDENT)),other=login(member(AccountRole.FACULTY));String b=book(CirculationPolicy.STANDARD);submit(student,b);assertEquals(1,json(mvc.perform(get("/api/v1/borrow-requests/mine").session(student)).andReturn()).get("totalElements").asInt());assertEquals(0,json(mvc.perform(get("/api/v1/borrow-requests/mine").session(other)).andReturn()).get("totalElements").asInt());assertEquals(409,post(student,"/api/v1/borrow-requests",Map.of("bookId",book(CirculationPolicy.REFERENCE_ONLY))).getResponse().getStatus());assertEquals(401,mvc.perform(get("/api/v1/borrow-requests/mine")).andReturn().getResponse().getStatus());}
 @Test void approvalDoesNotIssueAndOnlyLibrarianCanDecide()throws Exception{MockHttpSession student=login(member(AccountRole.STUDENT));String b=book(CirculationPolicy.STANDARD),r=submit(student,b),c=copy(b);assertEquals(403,post(student,"/api/v1/borrow-requests/"+r+"/decision",Map.of("decision","APPROVE")).getResponse().getStatus());MvcResult approved=post(lib,"/api/v1/borrow-requests/"+r+"/decision",Map.of("decision","APPROVE"));assertEquals("APPROVED",json(approved).get("status").asText());assertEquals("AVAILABLE",copies.findById(UUID.fromString(c)).orElseThrow().getStatus().name());assertEquals(0,json(mvc.perform(get("/api/v1/loans/mine").session(student)).andReturn()).get("totalElements").asInt());}
 @Test void issueUsesThirtyCalendarDaysAndAssignsCopyAtomically()throws Exception{MockHttpSession student=login(member(AccountRole.STUDENT));String b=book(CirculationPolicy.STANDARD),c=copy(b),r=submit(student,b);approve(r);MvcResult issued=issue(r,c);assertEquals(201,issued.getResponse().getStatus());JsonNode loan=json(issued);LocalDate issue=LocalDate.parse(loan.get("issueDate").asText());assertEquals(issue.plusDays(30),LocalDate.parse(loan.get("dueDate").asText()));assertEquals("ON_LOAN",copies.findById(UUID.fromString(c)).orElseThrow().getStatus().name());assertFalse(loan.has("fineAmount"));}
 @Test void competingApprovedRequestsCannotIssueTheSameCopyConcurrently()throws Exception{MockHttpSession a=login(member(AccountRole.STUDENT)),b=login(member(AccountRole.FACULTY));String book=book(CirculationPolicy.STANDARD),copy=copy(book),r1=submit(a,book),r2=submit(b,book);approve(r1);approve(r2);MockHttpSession libTwo=login(librarian);CountDownLatch start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var x=CompletableFuture.supplyAsync(()->issueAfter(start,lib,r1,copy),pool);var y=CompletableFuture.supplyAsync(()->issueAfter(start,libTwo,r2,copy),pool);start.countDown();int sx=x.get(15,TimeUnit.SECONDS),sy=y.get(15,TimeUnit.SECONDS);assertTrue((sx==201&&sy==409)||(sx==409&&sy==201),sx+" / "+sy);assertEquals("ON_LOAN",copies.findById(UUID.fromString(copy)).orElseThrow().getStatus().name());}finally{pool.shutdownNow();}}
 @Test void renewalIsLimitedToOneAndIsOwnerOnly()throws Exception{MockHttpSession student=login(member(AccountRole.STUDENT)),other=login(member(AccountRole.STUDENT));String b=book(CirculationPolicy.STANDARD),c=copy(b),r=submit(student,b);approve(r);String id=json(issue(r,c)).get("id").asText();LocalDate before=LocalDate.parse(json(mvc.perform(get("/api/v1/loans/mine").session(student)).andReturn()).get("content").get(0).get("dueDate").asText());MvcResult renewed=post(student,"/api/v1/loans/"+id+"/renew",Map.of());assertEquals(200,renewed.getResponse().getStatus());assertEquals(before.plusDays(30),LocalDate.parse(json(renewed).get("dueDate").asText()));assertEquals(1,json(renewed).get("renewalCount").asInt());assertEquals(409,post(student,"/api/v1/loans/"+id+"/renew",Map.of()).getResponse().getStatus());assertEquals(404,post(other,"/api/v1/loans/"+id+"/renew",Map.of()).getResponse().getStatus());}
 @Test void returnsUpdateCopyStateAndRepeatedReturnsConflict()throws Exception{MockHttpSession student=login(member(AccountRole.STUDENT));String b=book(CirculationPolicy.STANDARD),c=copy(b),r=submit(student,b);approve(r);String id=json(issue(r,c)).get("id").asText();assertEquals(409,post(lib,"/api/v1/loans/"+id+"/return",Map.of("condition","DAMAGED")).getResponse().getStatus());MvcResult returned=post(lib,"/api/v1/loans/"+id+"/return",Map.of("condition","DAMAGED","note","Damage recorded for policy review."));assertEquals(200,returned.getResponse().getStatus());assertEquals("DAMAGED",copies.findById(UUID.fromString(c)).orElseThrow().getStatus().name());assertEquals("RETURNED",json(returned).get("status").asText());assertEquals(409,post(lib,"/api/v1/loans/"+id+"/return",Map.of("condition","GOOD")).getResponse().getStatus());assertFalse(json(returned).has("replacementAmount"));}
 @Test void lostCaseIsRecordedWithoutInventingFineOrActualReturnDate()throws Exception{MockHttpSession student=login(member(AccountRole.STUDENT));String b=book(CirculationPolicy.STANDARD),c=copy(b),r=submit(student,b);approve(r);String id=json(issue(r,c)).get("id").asText();JsonNode response=json(post(lib,"/api/v1/loans/"+id+"/return",Map.of("condition","LOST","note","Member reports item lost.")));assertEquals("LOST",response.get("status").asText());assertTrue(response.get("actualReturnDate").isNull());assertEquals("LOST",copies.findById(UUID.fromString(c)).orElseThrow().getStatus().name());assertFalse(response.has("fineAmount"));}
 @Test void requestHistoryAndRoleBoundariesAreEnforced()throws Exception{MockHttpSession student=login(member(AccountRole.STUDENT)),faculty=login(member(AccountRole.FACULTY));String r=submit(student,book(CirculationPolicy.STANDARD));approve(r);JsonNode own=json(mvc.perform(get("/api/v1/borrow-requests/mine").session(student)).andReturn()).get("content").get(0);assertTrue(own.get("history").size()>=2);assertEquals(0,json(mvc.perform(get("/api/v1/borrow-requests/mine").session(faculty)).andReturn()).get("totalElements").asInt());assertEquals(403,mvc.perform(get("/api/v1/borrow-requests").session(faculty)).andReturn().getResponse().getStatus());assertEquals(403,mvc.perform(get("/api/v1/loans").session(faculty)).andReturn().getResponse().getStatus());}
 @Test void holidayServiceAdjustsConsecutiveConfiguredDaysAndLeavesOrdinaryWeekendsAlone(){assertEquals(LocalDate.of(2025,3,1),dueDates.initialDueDate(LocalDate.of(2025,1,30)));assertEquals(LocalDate.of(2025,3,31),dueDates.initialDueDate(LocalDate.of(2025,3,1)));assertEquals(LocalDate.of(2025,1,14),dueDates.initialDueDate(LocalDate.of(2024,12,15)));holidays.saveAndFlush(new LibraryHoliday(LocalDate.of(2035,1,14),"Configured closure A",librarian));holidays.saveAndFlush(new LibraryHoliday(LocalDate.of(2035,1,15),"Configured closure B",librarian));assertEquals(LocalDate.of(2035,1,16),dueDates.adjust(LocalDate.of(2035,1,14)));assertEquals(LocalDate.of(2035,1,13),dueDates.adjust(LocalDate.of(2035,1,14).minusDays(1)));}
 @Test void librarianCannotApproveOwnRequestAndOnlyLibrarianCanManageHolidays()throws Exception{Book entity=books.findById(UUID.fromString(book(CirculationPolicy.STANDARD))).orElseThrow();BorrowRequest own=requests.saveAndFlush(new BorrowRequest(librarian,entity,Instant.now()));assertEquals(409,post(lib,"/api/v1/borrow-requests/"+own.getId()+"/decision",Map.of("decision","APPROVE")).getResponse().getStatus());MockHttpSession student=login(member(AccountRole.STUDENT));assertEquals(403,post(student,"/api/v1/holidays",Map.of("holidayDate","2035-12-25","name","Test holiday")).getResponse().getStatus());assertEquals(201,post(lib,"/api/v1/holidays",Map.of("holidayDate","2035-12-25","name","Configured date")).getResponse().getStatus());}
 private UserAccount member(AccountRole role){String id=UUID.randomUUID().toString();return accounts.saveAndFlush(UserAccount.provisionMember(role.name().toLowerCase()+"-"+id+"@example.edu",encoder.encode(PASSWORD),role,role.name()+"-"+id,librarian.getId(),Instant.now()));}
 private MockHttpSession login(UserAccount a)throws Exception{MvcResult r=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/auth/login").with(csrf()).contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(Map.of("email",a.getEmail(),"password",PASSWORD)))).andReturn();assertEquals(200,r.getResponse().getStatus());return (MockHttpSession)r.getRequest().getSession();}
 private String book(CirculationPolicy policy)throws Exception{String u=UUID.randomUUID().toString();return json(post(lib,"/api/v1/books",Map.of("title","Test book "+u,"authors",new String[]{"Author "+u},"categories",new String[]{"Category "+u},"circulationPolicy",policy.name()))).get("id").asText();}
 private String copy(String b)throws Exception{return json(post(lib,"/api/v1/books/"+b+"/copies",Map.of("copyIdentifier","CP-"+UUID.randomUUID()))).get("id").asText();}
 private String submit(MockHttpSession s,String b)throws Exception{return json(post(s,"/api/v1/borrow-requests",Map.of("bookId",b))).get("id").asText();}
 private void approve(String r)throws Exception{assertEquals(200,post(lib,"/api/v1/borrow-requests/"+r+"/decision",Map.of("decision","APPROVE")).getResponse().getStatus());}
 private MvcResult issue(String r,String c)throws Exception{return post(lib,"/api/v1/borrow-requests/"+r+"/issue",Map.of("copyId",c));}
 private int issueAfter(CountDownLatch start,MockHttpSession s,String r,String c){try{start.await();return issueSession(s,r,c);}catch(Exception e){throw new RuntimeException(e);}}
 private int issueSession(MockHttpSession s,String r,String c)throws Exception{return post(s,"/api/v1/borrow-requests/"+r+"/issue",Map.of("copyId",c)).getResponse().getStatus();}
 private MvcResult post(MockHttpSession s,String path,Object value)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(path).session(s).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(value instanceof String x?x:mapper.writeValueAsString(value))).andReturn();}
 private JsonNode json(MvcResult result)throws Exception{return mapper.readTree(result.getResponse().getContentAsString());}
}


